const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
const k = Number(input[0]);
const va = BigInt(input[1]);
const vb = BigInt(input[2]);

const MOD = 1000000007n;

function powmod(a, exponent) {
    a %= MOD;
    let result = 1n;

    while (exponent > 0n) {
        if (exponent & 1n) {
            result = result * a % MOD;
        }
        a = a * a % MOD;
        exponent >>= 1n;
    }

    return result;
}

const den = powmod(va + vb, MOD - 2n);
const pa = va * den % MOD;
const pb = vb * den % MOD;
const oneB = pa * powmod(pb, MOD - 2n) % MOD;

const size = k + 1;
const dp = new BigInt64Array(size * size);

for (let i = k - 1; i >= 0; --i) {
    for (let j = k; j >= 1; --j) {
        const index = i * size + j;

        if (i + j >= k) {
            dp[index] = (BigInt(i + j) + oneB) % MOD;
        } else {
            dp[index] = (
                pa * dp[index + 1] +
                pb * dp[(i + j) * size + j]
            ) % MOD;
        }
    }
}

console.log(dp[1].toString());

